describe("dbRelationToCrossApp", () => {
  const conceptMap: Record<number, string> = {
    10: "orn:obsidian.schema:vault-a/relation-type-1",
    20: "orn:obsidian.note:vault-a/source-node-1",
    30: "orn:obsidian.note:vault-a/destination-node-1",
  };

  it("converts a relation, resolving type/source/destination to local ids", () => {
    const relation = baseConcept({
      is_schema: false,
      schema_id: 10,
      reference_content: { source: 20, destination: 30 },
    });
    expect(
      dbRelationToCrossApp({ relation, spaceMap, accountMap, conceptMap }),
    ).toEqual({
      rid: "orn:obsidian.relation:vault-a/concept-1",
      localId: "concept-1",
      authorId: "account-local-1",
      createdAt: new Date("2026-06-14T11:00:00Z"),
      modifiedAt: new Date("2026-06-14T13:00:00Z"),
      source: "source-node-1",
      destination: "destination-node-1",
      relationType: "relation-type-1",
    });
  });

  it("keeps source/destination as a full rid when it points to a different space", () => {
    const relation = baseConcept({
      is_schema: false,
      schema_id: 10,
      reference_content: { source: 20, destination: 30 },
    });
    const foreignConceptMap = {
      ...conceptMap,
      20: "orn:obsidian.note:vault-b/source-node-1",
    };
    expect(
      dbRelationToCrossApp({
        relation,
        spaceMap,
        accountMap,
        conceptMap: foreignConceptMap,
      }).source,
    ).toBe("orn:obsidian.note:vault-b/source-node-1");
  });

  it("throws when the relation type is missing", () => {
    const relation = baseConcept({
      is_schema: false,
      schema_id: 999,
      reference_content: { source: 20, destination: 30 },
    });
    expect(() =>
      dbRelationToCrossApp({ relation, spaceMap, accountMap, conceptMap }),
    ).toThrow("Missing relationType");
  });
});

describe("dbRelationsToCrossApp endpoint rids", () => {
  const crossSpaceMap: Record<number, string> = {
    1: "obsidian:vault-a",
    2: "obsidian:vault-b",
    3: "https://roamresearch.com/#/app/research-graph",
  };

  const conceptRows = [
    {
      id: 10,
      space_id: 1,
      source_local_id: "relation-type-1",
      is_schema: true,
      is_relation: true,
    },
    {
      id: 20,
      space_id: 2,
      source_local_id: "source-node-1",
      is_schema: false,
      is_relation: false,
    },
    {
      id: 30,
      space_id: 3,
      source_local_id: "roam-uid-1",
      is_schema: false,
      is_relation: false,
    },
  ];

  const makeClient = (): DGSupabaseClient => {
    const result = { data: conceptRows, error: null };
    const builder = {
      select: vi.fn(),
      in: vi.fn(),
      not: vi.fn(),
      then: (
        resolve: (value: typeof result) => unknown,
        reject?: (reason: unknown) => unknown,
      ) => Promise.resolve(result).then(resolve, reject),
    };
    builder.select.mockReturnValue(builder);
    builder.in.mockReturnValue(builder);
    builder.not.mockReturnValue(builder);
    return { from: vi.fn(() => builder) } as unknown as DGSupabaseClient;
  };

  const relation = baseConcept({
    is_schema: false,
    schema_id: 10,
    reference_content: { source: 20, destination: 30 },
  });

  // The Obsidian rid must match the `importedFrom.sourceNodeRid` Roam stores for
  // an imported note, or importSharedRelations cannot resolve the endpoint.
  it("gives an Obsidian endpoint the note subtype", async () => {
    const [converted] = await dbRelationsToCrossApp({
      client: makeClient(),
      relations: [relation],
      accountMap,
      spaceMap: crossSpaceMap,
    });
    expect(converted?.source).toBe("orn:obsidian.note:vault-b/source-node-1");
  });

  it("leaves a Roam endpoint as a url rid with no subtype", async () => {
    const [converted] = await dbRelationsToCrossApp({
      client: makeClient(),
      relations: [relation],
      accountMap,
      spaceMap: crossSpaceMap,
    });
    expect(converted?.destination).toBe(
      "https://roamresearch.com/#/app/research-graph/roam-uid-1",
    );
  });
});

import {
  CrossAppEmbedding,
  InlineCrossAppContent,
  CrossAppNode,
  CrossAppNodeSchema,
  CrossAppRelationTypeSchema,
  CrossAppRelationTripleSchema,
  CrossAppRelation,
} from "../crossAppContracts";
import { LocalContentDataInput, LocalConceptDataInput } from "../inputTypes";
import { ridToSpaceUriAndLocalId } from "./rid";
import { Enums, CompositeTypes } from "../dbTypes";

type InlineEmbeddingInput = CompositeTypes<"inline_embedding_input">;

const crossAppEmbeddingToDbEmbedding = (
  embedding: CrossAppEmbedding | undefined,
): InlineEmbeddingInput | undefined =>
  embedding === undefined
    ? undefined
    : {
        vector: embedding.value,
        model: embedding.embedding || "openai_text_embedding_3_small_1536",
      };

const filterUndefined = <T extends Record<string, unknown>>(data: T): T => {
  return Object.fromEntries(
    Object.entries(data).filter(([, v]) => v !== undefined),
  ) as T;
};

const filterUndefinedArray = <T>(data: (T | undefined)[]): T[] =>
  data.filter((v) => v !== undefined);

const inlineCrossAppContentToDbContent = (
  content: InlineCrossAppContent | undefined,
  variant: Enums<"ContentVariant">,
): LocalContentDataInput | undefined => {
  if (content === undefined) return undefined;
  return filterUndefined<LocalContentDataInput>({
    source_local_id: content.localId,
    text: content.value,
    scale: content.scale || "document",
    content_type: content.contentType || "text/plain",
    variant,
    created: content.createdAt?.toISOString(),
    last_modified: content.modifiedAt?.toISOString(),
    author_local_id: content.authorId,
    embedding_inline: crossAppEmbeddingToDbEmbedding(content.embedding),
  });
};

export const crossAppNodeToDbContent = (
  node: CrossAppNode | undefined,
  variant: "full" | "direct",
): LocalContentDataInput | undefined => {
  if (node === undefined) return undefined;
  const content = node.content[variant];
  if (content === undefined) return undefined;
  return inlineCrossAppContentToDbContent(
    {
      ...content,
      createdAt: content.createdAt || node.createdAt,
      modifiedAt: content.modifiedAt || node.modifiedAt,
      authorId: content.authorId || node.authorId,
    },
    variant,
  );
};

export const crossAppNodeToDbConcept = (
  node: CrossAppNode,
): LocalConceptDataInput => {
  const spaceUri = node.rid
    ? ridToSpaceUriAndLocalId(node.rid).spaceUri
    : undefined;
  return filterUndefined<LocalConceptDataInput>({
    space_url: spaceUri,
    source_local_id: node.localId,
    name: node.content.direct.value,
    author_local_id: node.authorId,
    schema_represented_by_local_id: node.nodeType,
    literal_content: {
      core_title: node.coreTitle,
    },
    contents_inline: filterUndefinedArray([
      crossAppNodeToDbContent(node, "direct"),
      crossAppNodeToDbContent(node, "full"),
    ]),
    created: node.createdAt?.toISOString(),
    last_modified: node.modifiedAt?.toISOString(),
    local_reference_content: node.slots,
  });
};

export const crossAppNodeSchemaToDbConcept = (
  node: CrossAppNodeSchema,
): LocalConceptDataInput => {
  const slots = Object.keys(node.slotDefinitions ?? {});
  const literalInfo = filterUndefined({
    label: node.label,
    template: node.templateTitle,
    template_content: node.template,
    format: node.format,
    roles: slots.length > 0 ? slots : undefined,
  });
  const referenceContent = slots.length ? node.slotDefinitions : undefined;
  const spaceUri = node.rid
    ? ridToSpaceUriAndLocalId(node.rid).spaceUri
    : undefined;
  return filterUndefined<LocalConceptDataInput>({
    space_url: spaceUri,
    source_local_id: node.localId,
    name: node.label,
    author_local_id: node.authorId,
    is_schema: true,
    literal_content:
      Object.keys(literalInfo).length > 0 ? literalInfo : undefined,
    local_reference_content: referenceContent,
    created: node.createdAt?.toISOString(),
    last_modified: node.modifiedAt?.toISOString(),
  });
};

export const crossAppRelationTypeSchemaToDbConcept = (
  node: CrossAppRelationTypeSchema,
): LocalConceptDataInput => {
  const spaceUri = node.rid
    ? ridToSpaceUriAndLocalId(node.rid).spaceUri
    : undefined;
  return filterUndefined<LocalConceptDataInput>({
    space_url: spaceUri,
    source_local_id: node.localId,
    name: node.label,
    author_local_id: node.authorId,
    is_schema: true,
    literal_content: {
      roles: ["source", "destination"],
      label: node.label,
      complement: node.complement,
    },
    created: node.createdAt?.toISOString(),
    last_modified: node.modifiedAt?.toISOString(),
  });
};

export const crossAppRelationTripleSchemaToDbConcept = (
  node: CrossAppRelationTripleSchema,
  // used in Obsidian, not yet in Roam.
  relationType?: CrossAppRelationTypeSchema,
): LocalConceptDataInput | undefined => {
  if (!("label" in node) && relationType === undefined) return undefined;
  const label = "label" in node ? node.label : relationType!.label;
  const complement =
    "complement" in node ? node.complement : relationType!.complement;
  const spaceUri = node.rid
    ? ridToSpaceUriAndLocalId(node.rid).spaceUri
    : undefined;
  return filterUndefined<LocalConceptDataInput>({
    space_url: spaceUri,
    source_local_id: node.localId,
    name: node.localId, // has to be unique within space. Not seen yet.
    author_local_id: node.authorId,
    is_schema: true,
    literal_content: filterUndefined({
      roles: ["source", "destination"],
      label,
      complement,
    }),
    local_reference_content: {
      relation_type: node.relation,
      source: node.sourceType,
      destination: node.destinationType,
    },
    created: node.createdAt?.toISOString(),
    last_modified: node.modifiedAt?.toISOString(),
  });
};

export const crossAppRelationToDbConcept = (
  node: CrossAppRelation,
): LocalConceptDataInput => {
  const spaceUri = node.rid
    ? ridToSpaceUriAndLocalId(node.rid).spaceUri
    : undefined;
  return filterUndefined<LocalConceptDataInput>({
    // use LocalIds... not ideal
    name: `${node.localId}: ${node.source} -${node.relationType}-> ${node.destination}`,
    space_url: spaceUri,
    source_local_id: node.localId,
    author_local_id: node.authorId,
    schema_represented_by_local_id: node.relationType,
    local_reference_content: {
      source: node.source,
      destination: node.destination,
    },
    created: node.createdAt?.toISOString(),
    last_modified: node.modifiedAt?.toISOString(),
  });
};

